use serde::{Deserialize, Serialize};

use crate::types::wire_tag::MessageTag;
use crate::types::{
    CacheDiagnostics, ContainerInfo, ContentBlock, ContextManagementResponse, MessageRole, Model,
    StopDetails, StopReason, Usage,
};

/// A message generated by the assistant.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[non_exhaustive]
pub struct Message {
    /// Unique object identifier.
    ///
    /// The format and length of IDs may change over time.
    pub id: String,

    /// Content generated by the model.
    ///
    /// This is an array of content blocks, each of which has a `type` that determines
    /// its shape.
    pub content: Vec<ContentBlock>,

    /// The model that generated the message.
    pub model: Model,

    /// Conversational role of the generated message.
    ///
    /// This will always be "assistant".
    pub role: MessageRole,

    /// The reason that generation stopped.
    ///
    /// This may be null in streaming responses until completion.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stop_reason: Option<StopReason>,

    /// Which custom stop sequence was generated, if any.
    ///
    /// This value will be a non-null string if one of your custom stop sequences was
    /// generated.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stop_sequence: Option<String>,

    /// Additional refusal information; null or absent for other stop reasons.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub stop_details: Option<Box<StopDetails>>,

    /// The container used by this request, when code execution or skills ran.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub container: Option<ContainerInfo>,

    /// Cache diagnostics, when the request opted in.
    ///
    /// Absent or `null` means there was no comparison or no divergence;
    /// `{"cache_miss_reason": null}` means the comparison is still running; a
    /// reason names the earliest divergence from the previous request.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub diagnostics: Option<CacheDiagnostics>,

    /// Context-management edits that were applied to this request.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub context_management: Option<ContextManagementResponse>,

    /// Object type, always `"message"`.
    r#type: MessageTag,

    /// Billing and rate-limit usage information.
    pub usage: Usage,
}

impl Message {
    /// Create a new `Message` with the given parameters.
    #[must_use]
    pub fn new(
        id: impl Into<String>,
        content: Vec<ContentBlock>,
        model: Model,
        usage: Usage,
    ) -> Self {
        Self {
            id: id.into(),
            content,
            model,
            role: MessageRole::Assistant,
            stop_reason: None,
            stop_sequence: None,
            stop_details: None,
            container: None,
            diagnostics: None,
            context_management: None,
            r#type: MessageTag,
            usage,
        }
    }

    /// Set the stop reason.
    #[must_use]
    pub fn with_stop_reason(mut self, stop_reason: StopReason) -> Self {
        self.stop_reason = Some(stop_reason);
        self
    }

    /// Set the stop sequence.
    #[must_use]
    pub fn with_stop_sequence(mut self, stop_sequence: impl Into<String>) -> Self {
        self.stop_sequence = Some(stop_sequence.into());
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::{CacheMissType, KnownModel, TextBlock};
    use serde_json::{json, to_value};

    #[test]
    fn message_serialization() {
        let text_block = TextBlock::new("Hello, I'm Claude.");
        let content = vec![ContentBlock::Text(text_block)];
        let model = Model::Known(KnownModel::ClaudeSonnet55);
        let usage = Usage::new(50, 100);

        let message = Message::new("msg_012345", content, model, usage);

        let json = to_value(&message).unwrap();
        assert_eq!(
            json,
            json!({
                "id": "msg_012345",
                "content": [
                    {
                        "text": "Hello, I'm Claude.",
                        "type": "text"
                    }
                ],
                "model": "claude-sonnet-5-5",
                "role": "assistant",
                "type": "message",
                "usage": {
                    "input_tokens": 50,
                    "output_tokens": 100
                }
            })
        );
    }

    #[test]
    fn message_with_stop_reason() {
        let text_block = TextBlock::new("Hello, I'm Claude.");
        let content = vec![ContentBlock::Text(text_block)];
        let model = Model::Known(KnownModel::ClaudeSonnet55);
        let usage = Usage::new(50, 100);

        let message =
            Message::new("msg_012345", content, model, usage).with_stop_reason(StopReason::EndTurn);

        let json = to_value(&message).unwrap();
        assert_eq!(
            json,
            json!({
                "id": "msg_012345",
                "content": [
                    {
                        "text": "Hello, I'm Claude.",
                        "type": "text"
                    }
                ],
                "model": "claude-sonnet-5-5",
                "role": "assistant",
                "stop_reason": "end_turn",
                "type": "message",
                "usage": {
                    "input_tokens": 50,
                    "output_tokens": 100
                }
            })
        );
    }

    #[test]
    fn message_deserialization() {
        let json = json!({
            "id": "msg_012345",
            "content": [
                {
                    "text": "Hello, I'm Claude.",
                    "type": "text"
                }
            ],
            "model": "claude-sonnet-5-5",
            "role": "assistant",
            "stop_reason": "end_turn",
            "stop_sequence": "###",
            "type": "message",
            "usage": {
                "input_tokens": 50,
                "output_tokens": 100,
                "server_tool_use": {
                    "web_search_requests": 5
                }
            }
        });

        let message: Message = serde_json::from_value(json).unwrap();
        assert_eq!(message.id, "msg_012345");
        assert_eq!(message.role, MessageRole::Assistant);
        assert_eq!(message.r#type, MessageTag);
        assert_eq!(message.stop_reason, Some(StopReason::EndTurn));
        assert_eq!(message.stop_sequence, Some("###".to_string()));

        assert_eq!(message.content.len(), 1);
        match &message.content[0] {
            ContentBlock::Text(text_block) => {
                assert_eq!(text_block.text, "Hello, I'm Claude.");
            }
            _ => panic!("Expected Text variant"),
        }

        match message.model {
            Model::Known(model) => {
                assert_eq!(model, KnownModel::ClaudeSonnet55);
            }
            _ => panic!("Expected Known model variant"),
        }

        assert_eq!(message.usage.input_tokens, 50);
        assert_eq!(message.usage.output_tokens, 100);
        // We'll verify server_tool_use in a future PR when ServerToolUsage is properly implemented
    }

    fn message_json() -> serde_json::Value {
        json!({
            "id": "msg_01",
            "content": [{"type": "text", "text": "hi"}],
            "model": "claude-sonnet-5-5",
            "role": "assistant",
            "type": "message",
            "usage": {"input_tokens": 1, "output_tokens": 2}
        })
    }

    #[test]
    fn message_deserializes_cache_diagnostics_reason() {
        let mut value = message_json();
        value["diagnostics"] = json!({
            "cache_miss_reason": {"type": "system_changed", "cache_missed_input_tokens": 41850}
        });
        let message: Message = serde_json::from_value(value).unwrap();
        let reason = message.diagnostics.unwrap().cache_miss_reason.unwrap();
        assert_eq!(reason.r#type, CacheMissType::SystemChanged);
        assert_eq!(reason.cache_missed_input_tokens, Some(41850));
    }

    #[test]
    fn message_deserializes_running_and_null_diagnostics() {
        let mut value = message_json();
        value["diagnostics"] = json!({"cache_miss_reason": null});
        let message: Message = serde_json::from_value(value).unwrap();
        assert_eq!(message.diagnostics.unwrap().cache_miss_reason, None);

        let mut value = message_json();
        value["diagnostics"] = serde_json::Value::Null;
        let message: Message = serde_json::from_value(value).unwrap();
        assert_eq!(message.diagnostics, None);
    }

    #[test]
    fn message_deserializes_container_and_context_management() {
        let mut value = message_json();
        value["container"] = json!({
            "id": "container_011",
            "expires_at": "2026-10-19T12:00:00Z",
            "skills": [{"type": "anthropic", "skill_id": "pptx", "version": "1"}]
        });
        value["context_management"] = json!({
            "applied_edits": [
                {"type": "clear_tool_uses_20250919", "cleared_input_tokens": 12000, "cleared_tool_uses": 4}
            ]
        });
        value["stop_reason"] = json!("compaction");
        let message: Message = serde_json::from_value(value).unwrap();
        assert_eq!(message.container.unwrap().id, "container_011");
        let edit = &message.context_management.unwrap().applied_edits[0];
        assert_eq!(edit.cleared_input_tokens, Some(12000));
        assert_eq!(edit.cleared_tool_uses, Some(4));
        assert_eq!(message.stop_reason, Some(StopReason::Compaction));
    }

    #[test]
    fn message_new_fields_omitted_when_absent() {
        let message: Message = serde_json::from_value(message_json()).unwrap();
        let value = to_value(&message).unwrap();
        for key in ["container", "diagnostics", "context_management"] {
            assert!(value.get(key).is_none());
        }
    }
}
